"""Render evals/REPORT.md from a results file (docs/plan.md §1.4: generated by code, with failure analysis).

Nothing is written by hand into the report: figures come from the results JSON, and the failure analysis pairs
every miss with its note in evals/failure_notes.yaml (why it happened, what changed). A miss with no note is
printed as "not yet analysed", so an unexplained failure is visible rather than silently dropped.
"""

from __future__ import annotations

import re
from pathlib import Path

import yaml

NOTES = Path(__file__).resolve().parent / "failure_notes.yaml"
ICON = {"pass": "PASS", "fail": "FAIL", "report": "report", "skipped": "skipped"}


def load_notes(path: Path = NOTES) -> list[dict]:
    return yaml.safe_load(path.read_text(encoding="utf-8"))["notes"] if path.exists() else []


def note_for(miss_id: str, notes: list[dict]) -> dict | None:
    """The first note whose `match` (a regex over the miss id) matches."""
    return next((n for n in notes if re.search(n["match"], miss_id)), None)


def _cell(value: object) -> str:
    return str(value).replace("|", "\\|").replace("\n", " ")


def render(results: dict, notes: list[dict] | None = None) -> str:
    notes = load_notes() if notes is None else notes
    sections = results["sections"]
    lines = [
        "# Evaluation report — M3 Trusted Data Foundation",
        "",
        f"Generated by `evals/run_evals.py` at {results['generated_at']} from commit `{results['commit']}` "
        f"on a database rebuilt from `data/` (`{results['database']}`). "
        "Do not edit by hand: run `make eval`.",
        "",
        "Model-dependent sections (LLM mapping, grounded answers, the exception agent) cost real API calls "
        "and are read from their latest saved run; the **Source** column says which.",
        "",
        "## Summary",
        "",
        "| Evaluation | Target | Result | Status | Source |",
        "|---|---|---|---|---|",
    ]
    for s in sections:
        lines.append(
            f"| {_cell(s['title'])} | {_cell(s['target'])} | {_cell(s['value'])} | {ICON[s['status']]} | "
            f"{_cell(s['source'])} |"
        )
    failing = [s for s in sections if s["status"] == "fail"]
    lines += [
        "",
        f"**{sum(s['status'] == 'pass' for s in sections)} pass, {len(failing)} fail, "
        f"{sum(s['status'] == 'report' for s in sections)} reported, "
        f"{sum(s['status'] == 'skipped' for s in sections)} skipped.**",
    ]
    if failing:
        lines += ["", "Failing: " + "; ".join(s["title"] for s in failing) + ". See the failure analysis."]

    lines += [
        "",
        "## Failure analysis",
        "",
        "One line per miss: what happened, why, what changed. Notes live in `evals/failure_notes.yaml`.",
        "",
    ]
    total = 0
    unanalysed = 0
    for s in sections:
        if not s["misses"]:
            continue
        lines += [
            f"### {s['title']}",
            "",
            "| Miss | What happened | Why | What changed |",
            "|---|---|---|---|",
        ]
        grouped: dict[str, list[dict]] = {}
        for miss in s["misses"]:
            note = note_for(miss["id"], notes)
            key = note["match"] if note else miss["id"]
            grouped.setdefault(key, []).append(miss)
        for misses in grouped.values():
            note = note_for(misses[0]["id"], notes)
            total += len(misses)
            label = misses[0]["id"] if len(misses) == 1 else f"{misses[0]['id']} (+{len(misses) - 1} alike)"
            what = (
                misses[0]["what"] if len(misses) == 1 else f"{len(misses)} misses, e.g. {misses[0]['what']}"
            )
            if note is None:
                unanalysed += len(misses)
            lines.append(
                f"| `{_cell(label)}` | {_cell(what)} | "
                f"{_cell(note['why']) if note else 'not yet analysed'} | "
                f"{_cell(note['changed']) if note else 'not yet analysed'} |"
            )
        lines.append("")
    if total == 0:
        lines.append("No misses.")
    lines += ["", f"{total} misses; {unanalysed} not yet analysed.", "", "## Details", ""]
    for s in sections:
        lines += [
            f"### {s['title']}",
            "",
            f"- Status: **{ICON[s['status']]}** — {s['value']}",
            f"- Target: {s['target']}",
            f"- Source: {s['source']}; took {s.get('seconds', '?')} s",
            "",
        ]
        details = s.get("details") or {}
        if s["id"] == "retrieval" and "challenges" in details:
            modes = list(details["totals"])
            lines += ["| Challenge | " + " | ".join(modes) + " |", "|---|" + "---|" * len(modes)]
            by = {(c["challenge"], c["mode"]): c for c in details["challenges"]}
            for ch in sorted({c["challenge"] for c in details["challenges"]}, key=lambda c: int(c[1:])):
                cells = []
                for m in modes:
                    c = by[(ch, m)]
                    recall = "–" if c["doc_recall"] is None else f"{c['doc_recall']:.0%}"
                    cells.append(f"{recall} ({c['questions']})")
                lines.append(f"| {ch} | " + " | ".join(cells) + " |")
            lines += ["", "Doc recall per challenge and mode (questions in brackets).", ""]
        if s["id"] == "agent" and "per_pattern" in details:
            lines += ["| Pattern | Expected | n | Accuracy | Outcomes |", "|---|---|---|---|---|"]
            for pid, p in details["per_pattern"].items():
                lines.append(
                    f"| {pid} | {p['expected']} | {p['n']} | {p['accuracy']:.0%} | {_cell(p['outcomes'])} |"
                )
            lines.append("")
        if s["id"] == "onboarding":
            lines += [f"- {details.get('note', '')}", ""]
    return "\n".join(lines).rstrip("\n") + "\n"
